INSERT INTO recipes (id, title, servings, total_minutes, equipment_json, instructions_json, tags_json, preference_weight, slot) VALUES ('bulk2-chicken-soboro-don', '鶏そぼろと卵の三色丼', 1, 25, '["フライパン", "電子レンジ"]', '["温かい炊飯済みの{{rice}}を用意する。", "{{broccoli}}を小房に分け、耐熱容器に入れて電子レンジ600Wで約2分加熱する。熱い蒸気に注意する。", "フライパンに{{oil}}を熱し、{{ground_meat}}をほぐしながら炒める。生肉に触れた手・包丁・まな板を洗う。", "{{soy}}と{{sugar}}を加えてそぼろに味をつけ、肉の中心が75℃に達してから1分以上加熱する。", "空いたフライパンを拭き、{{egg}}を溶いて炒り卵にし、中心が75℃に達してから1分以上加熱する。", "ご飯にそぼろ、炒り卵、ブロッコリーをのせて盛り付ける。"]', '["増量", "昼食", "概算"]', 0, 'lunch');
