INSERT INTO recipes (id, title, servings, total_minutes, equipment_json, instructions_json, tags_json, preference_weight, slot) VALUES ('bulk2-tuna-egg-cheese-don', 'ツナエッグチーズ丼', 1, 20, '["フライパン"]', '["温かい炊飯済みの{{rice}}を用意する。{{onion}}を薄切りにする。", "フライパンに{{oil}}を熱し、たまねぎを炒める。{{canned_tuna}}を加えてほぐしながら温める。", "{{egg}}を溶いて回し入れ、中心が75℃に達してから1分以上加熱する。", "{{soy}}で味を調え、{{cheese}}をのせて余熱で溶かし、ご飯にのせる。"]', '["増量", "昼食", "概算"]', 0, 'lunch');
