INSERT INTO recipes (id, title, servings, total_minutes, equipment_json, instructions_json, tags_json, preference_weight, slot) VALUES ('bulk2-salmon-mayo-don', 'さけマヨ丼', 1, 20, '["フライパン", "電子レンジ"]', '["温かい炊飯済みの{{rice}}を用意する。{{broccoli}}を小房に分け、電子レンジ600Wで約2分加熱する。熱い蒸気に注意する。", "フライパンに{{oil}}を熱し、{{salmon}}を両面焼く。魚に触れた手・包丁・まな板を洗い、中心が75℃に達してから1分以上加熱する。", "{{egg}}を耐熱容器に割り、電子レンジで加熱して中心が75℃に達してから1分以上加熱する。", "ほぐしたさけと卵、ブロッコリーをご飯にのせ、{{mayo}}をかけ、{{soy}}を少量かける。"]', '["増量", "昼食", "概算"]', 0, 'lunch');
