INSERT INTO recipes (id, title, servings, total_minutes, equipment_json, instructions_json, tags_json, preference_weight, slot) VALUES ('bulk2-keema-curry-don', '挽き肉と豆腐のカレー丼', 1, 25, '["フライパン"]', '["温かい炊飯済みの{{rice}}を用意する。{{onion}}を薄切り、{{carrot}}を短冊切りにし、{{tofu}}を2cm角に切る。", "フライパンに{{oil}}を熱し、{{ground_meat}}とたまねぎ、にんじんを炒める。生肉に触れた手・包丁・まな板を洗う。", "{{curry}}と{{soy}}、水少量を加え、豆腐を加えて煮絡める。肉の中心が75℃に達してから1分以上加熱する。", "ご飯にかけて盛り付ける。"]', '["増量", "昼食", "概算"]', 0, 'lunch');
