INSERT INTO recipes (id, title, servings, total_minutes, equipment_json, instructions_json, tags_json, preference_weight, slot) VALUES ('bulk2-saba-miso-set', 'サバ缶と豆腐のみそ煮定食', 1, 20, '["鍋"]', '["温かい炊飯済みの{{rice}}を用意する。{{tofu}}を2cm角に切り、{{broccoli}}を小房に分ける。{{ginger}}をすりおろす。", "鍋に{{canned_mackerel}}を汁ごと入れ、{{miso}}、{{sugar}}、すりおろしたしょうが、水少量を加えて温める。", "豆腐とブロッコリーを加え、全体が十分に温まるまで煮る。", "ご飯と一緒に盛り付ける。"]', '["増量", "夕食", "概算"]', 0, 'dinner');
