INSERT INTO recipes (id, title, servings, total_minutes, equipment_json, instructions_json, tags_json, preference_weight, slot) VALUES ('bulk2-chicken-hoikoro-don', '鶏肉の回鍋肉風丼', 1, 20, '["フライパン"]', '["温かい炊飯済みの{{rice}}を用意する。{{chicken}}を一口大に切り、{{cabbage}}をざく切り、{{onion}}を薄切りにする。生肉に触れた手・包丁・まな板を洗う。", "フライパンに{{oil}}を熱し、鶏肉とたまねぎを焼く。中心が75℃に達してから1分以上加熱する。", "キャベツを加えて炒め、{{miso}}、{{sugar}}、{{soy}}を絡める。", "ご飯にのせて盛り付ける。"]', '["増量", "夕食", "概算"]', 0, 'dinner');
