INSERT INTO recipes (id, title, servings, total_minutes, equipment_json, instructions_json, tags_json, preference_weight, slot) VALUES ('bulk2-tofu-hamburg-don', '豆腐ハンバーグ丼', 1, 25, '["フライパン"]', '["温かい炊飯済みの{{rice}}を用意する。{{tofu}}をキッチンペーパーで包んで水切りし、{{onion}}をみじん切りにする。", "{{ground_meat}}、水切りした豆腐、たまねぎ、{{egg}}をよく混ぜ、小判形にまとめる。生肉に触れた手・道具を洗う。", "フライパンに{{oil}}を熱して両面を焼き、中心が75℃に達してから1分以上加熱する。", "{{soy}}と{{sugar}}を絡め、ご飯にのせる。"]', '["増量", "夕食", "概算"]', 0, 'dinner');
