INSERT INTO recipes (id, title, servings, total_minutes, equipment_json, instructions_json, tags_json, preference_weight, slot) VALUES ('bulk2-tuna-tomato-pasta', 'ツナとトマトのパスタ', 1, 25, '["鍋", "フライパン"]', '["鍋で{{pasta}}を表示時間どおりゆでる。{{tomato}}を1cm角に、{{onion}}を薄切りにする。", "フライパンに{{oil}}を熱し、たまねぎとトマトを炒める。{{canned_tuna}}を加えてほぐしながら温める。", "ゆで上がったパスタとゆで汁少量を加え、{{soy}}で味を調える。", "{{cheese}}をのせて余熱で溶かす。"]', '["増量", "夕食", "概算"]', 0, 'dinner');
